DROP TABLE IF EXISTS `production_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `production_records` (
  `id` int NOT NULL AUTO_INCREMENT,
  `report_id` varchar(50) DEFAULT NULL,
  `report_date` date DEFAULT NULL,
  `line_name` varchar(50) DEFAULT NULL,
  `section` varchar(100) DEFAULT NULL,
  `shift` varchar(20) DEFAULT NULL,
  `drafter_name` varchar(100) DEFAULT NULL,
  `supervisor_name` varchar(100) DEFAULT NULL,
  `hod_name` varchar(255) DEFAULT NULL,
  `work_from` time DEFAULT NULL,
  `work_to` time DEFAULT NULL,
  `model_name` varchar(100) DEFAULT NULL,
  `uph` int DEFAULT NULL,
  `h1_qty` int DEFAULT NULL,
  `h2_qty` int DEFAULT NULL,
  `h3_qty` int DEFAULT NULL,
  `h4_qty` int DEFAULT NULL,
  `h5_qty` int DEFAULT NULL,
  `h6_qty` int DEFAULT NULL,
  `h7_qty` int DEFAULT NULL,
  `h8_qty` int DEFAULT NULL,
  `h9_qty` int DEFAULT NULL,
  `h10_qty` int DEFAULT NULL,
  `h11_qty` int DEFAULT NULL,
  `total_qty` int DEFAULT NULL,
  `input_qty` int DEFAULT '0',
  `scrap_qty` int DEFAULT NULL,
  `repair_qty` int DEFAULT NULL,
  `remarks` text,
  `mp_direct` int DEFAULT '0',
  `mp_indirect` int DEFAULT '0',
  `mp_contractor` int DEFAULT '0',
  `is_deleted` int DEFAULT '0',
  `deleted_by` varchar(100) DEFAULT NULL,
  `status` varchar(20) DEFAULT 'Pending',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `is_approved` int DEFAULT '0',
  `is_verified` int DEFAULT '0',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `packing_qty` int DEFAULT '0',
  `ot_hrs` decimal(5,2) DEFAULT '0.00',
  `total_hrs` decimal(5,2) DEFAULT '0.00',
  `live_row_token` varchar(64) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=10079 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
